#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll MOD = 1000000007;

ll modPower(ll base, ll exponent) {
    base %= MOD;
    ll result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, n, x;
    cin >> a >> b >> n >> x;

    a %= MOD;
    b %= MOD;
    x %= MOD;

    ll answer;
    if (a == 1) {
        answer = (x + b * (n % MOD)) % MOD;
    } else {
        ll an = modPower(a, n);
        ll inverse = modPower((a - 1 + MOD) % MOD, MOD - 2);
        ll geometricSum = (an - 1 + MOD) % MOD * inverse % MOD;
        answer = (an * x % MOD + b * geometricSum % MOD) % MOD;
    }

    cout << answer;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

const ll MOD = 1000000007;

ll multiplyMod(ll a, ll b) {
    return static_cast<ll>((i128)a * b % MOD);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll a, b, n, x;
    cin >> a >> b >> n >> x;

    a = (a % MOD + MOD) % MOD;
    b = (b % MOD + MOD) % MOD;
    x = (x % MOD + MOD) % MOD;

    ll resultA = 1;
    ll resultB = 0;

    while (n > 0) {
        if (n & 1) {
            resultB = (multiplyMod(a, resultB) + b) % MOD;
            resultA = multiplyMod(a, resultA);
        }

        b = (multiplyMod(a, b) + b) % MOD;
        a = multiplyMod(a, a);
        n >>= 1;
    }

    cout << (multiplyMod(resultA, x) + resultB) % MOD;
    return 0;
}

