#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

constexpr int64 MOD = 1000000007;

int64 multiplyMod(int64 a, int64 b) {
    return static_cast<int64>((i128)a * b % MOD);
}

int64 powerMod(int64 base, int64 exponent) {
    base %= MOD;
    int64 result = 1;
    while (exponent > 0) {
        if (exponent & 1)
            result = multiplyMod(result, base);
        base = multiplyMod(base, base);
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 a, b, n, x;
    cin >> a >> b >> n >> x;

    a %= MOD;
    b %= MOD;
    x %= MOD;

    int64 answer;
    if (a == 1) {
        answer = (x + multiplyMod(b, n % MOD)) % MOD;
    } else {
        int64 an = powerMod(a, n);
        int64 inverse = powerMod((a - 1 + MOD) % MOD, MOD - 2);
        int64 geometricSum = multiplyMod((an - 1 + MOD) % MOD, inverse);
        answer = (multiplyMod(an, x) + multiplyMod(b, geometricSum)) % MOD;
    }

    cout << answer;
    return 0;
}

